<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1 class="h3 mb-1">Welcome, <?= esc($user['name']) ?></h1><p class="text-secondary mb-0">Your ticket operations at a glance.</p></div><?php if ($user['role'] === 'Employee'): ?><a class="btn btn-primary" href="<?= site_url('tickets/new') ?>">Create ticket</a><?php endif ?></div>
<div class="row g-3 mb-4"><?php foreach (['Open', 'In Progress', 'Resolved', 'Closed'] as $status): $count = 0; foreach ($counts as $row) if ($row['status'] === $status) $count = $row['total']; ?><div class="col-6 col-lg-3"><div class="card h-100"><div class="card-body"><div class="text-secondary small"><?= esc($status) ?></div><div class="display-6"><?= (int) $count ?></div></div></div></div><?php endforeach ?></div>
<?php if ($user['role'] === 'IT Manager'): ?><div class="card mb-4"><div class="card-header">Active support workload</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>IT Support</th><th>Assigned tickets</th></tr></thead><tbody><?php foreach ($workload as $row): ?><tr><td><?= esc($row['name']) ?></td><td><?= (int) $row['total'] ?></td></tr><?php endforeach ?></tbody></table></div></div><?php endif ?>
<div class="card"><div class="card-header d-flex justify-content-between"><span>Recent tickets</span><a href="<?= site_url('tickets') ?>">View all</a></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Ticket</th><th>Subject</th><th>Status</th><th>Priority</th><th>Created</th></tr></thead><tbody><?php foreach ($tickets as $ticket): ?><tr><td><a href="<?= site_url('tickets/' . $ticket['id']) ?>"><?= esc($ticket['ticket_number']) ?></a></td><td><?= esc($ticket['subject']) ?></td><td><?= esc($ticket['status']) ?></td><td><?= esc($ticket['priority']) ?></td><td><?= esc($ticket['created_at']) ?></td></tr><?php endforeach ?><?php if (! $tickets): ?><tr><td colspan="5" class="text-secondary text-center py-4">No tickets yet.</td></tr><?php endif ?></tbody></table></div></div>
